import React from 'react';
import { Line } from 'react-chartjs-2';

const ComparisonCharts = ({ dqnData = [], otherAlgorithmData = [] }) => {
    if (!Array.isArray(dqnData) || !Array.isArray(otherAlgorithmData)) {
        return <div>No data to display.</div>;
    }

    const chartData = {
        labels: dqnData.map((_, index) => index + 1),
        datasets: [
            {
                label: 'DQN Algorithm',
                data: dqnData,
                borderColor: 'rgba(75, 192, 192, 1)',
                backgroundColor: 'rgba(75, 192, 192, 0.2)',
                fill: true,
            },
            {
                label: 'Other Algorithm',
                data: otherAlgorithmData,
                borderColor: 'rgba(255, 99, 132, 1)',
                backgroundColor: 'rgba(255, 99, 132, 0.2)',
                fill: true,
            },
        ],
    };

    const options = {
        responsive: true,
        scales: {
            y: {
                beginAtZero: true,
            },
        },
    };

    return (
        <div>
            <h2>Comparison of Algorithms</h2>
            <Line data={chartData} options={options} />
        </div>
    );
};

export default ComparisonCharts;
